/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    normalizeRawTsvRow, renderFandomMarkdownTable, convertFandomScalingAbilityMatrices, preprocessFandomRawTableRegions, looksLikeDotSeparatedTableFallback, countMarkdownTableRows
 * depends    —
 * used by    src/mechanics/calculators/specs-generated, src/wiki/fandom/index, src/wiki/fandom/wikitext-table, src/wiki/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
const SCALING_BLOCK_HEADER = /^\d+\s+Base Scaling$/i
const TOTAL_COST_METADATA = /^Total Cost:\s*[\d,]+$/i

function isBlankLine(line: string): boolean {
  return line.trim() === ''
}

function isTableRowLine(line: string): boolean {
  if (!line.includes('\t')) return false
  const cells = line.split('\t').map(normalizeRawTsvCell)
  return cells.length >= 2 && cells.some((cell, index) => index === 0 ? cell.length > 0 : true)
}

function normalizeRawTsvCell(cell: string): string {
  return cell.trim().replace(/^\|+/, '').trim()
}

export function normalizeRawTsvRow(row: string): string {
  return row.split('\t').map(normalizeRawTsvCell).join('\t')
}

function escapeTableCell(value: string): string {
  return value.replace(/\|/g, '\\|').replace(/\n/g, '<br>').trim()
}

function isFeatureTitleLine(line: string): boolean {
  const trimmed = line.trim()
  if (!trimmed || trimmed.includes('\t')) return false
  if (trimmed.length > 96) return false
  return /^.+\s-\s.+$/.test(trimmed)
}

export function renderFandomMarkdownTable(rows: string[][]): string[] {
  if (rows.length === 0) return []
  const width = Math.max(...rows.map(row => row.length))
  const normalized = rows.map(row => {
    const cells = [...row]
    while (cells.length < width) cells.push('')
    return cells.slice(0, width).map(escapeTableCell)
  })

  const [header, ...body] = normalized
  const lines = [
    `| ${header.join(' | ')} |`,
    `| ${header.map(() => '---').join(' | ')} |`,
  ]
  for (const row of body) {
    lines.push(`| ${row.join(' | ')} |`)
  }
  lines.push('')
  return lines
}

function collectScalingMatrixSegment(
  lines: string[],
  startIndex: number,
): { rows: string[][]; nextIndex: number } | null {
  const scalingLine = lines[startIndex]?.trim() ?? ''
  if (!SCALING_BLOCK_HEADER.test(scalingLine)) return null

  let index = startIndex + 1
  let totalCost = ''
  if (TOTAL_COST_METADATA.test(lines[index]?.trim() ?? '')) {
    totalCost = lines[index]?.trim() ?? ''
    index += 1
  }

  while (index < lines.length && isBlankLine(lines[index] ?? '')) index += 1

  const unlockLine = lines[index]?.trim() ?? ''
  if (!isTableRowLine(unlockLine) || !/^unlock\t/i.test(unlockLine)) return null

  const unlockCells = unlockLine.split('\t').map(normalizeRawTsvCell)
  const tierCell = totalCost ? `${scalingLine}<br>${totalCost}` : scalingLine
  const headerRow = [tierCell, ...unlockCells]
  const bodyRows: string[][] = []

  index += 1
  while (index < lines.length) {
    while (index < lines.length && isBlankLine(lines[index] ?? '')) index += 1
    if (index >= lines.length) break

    const trimmed = lines[index]?.trim() ?? ''
    if (!trimmed) break
    if (SCALING_BLOCK_HEADER.test(trimmed)) break
    if (/^(list of ultimate weapons|ultimate weapon plus)$/i.test(trimmed)) break

    if (isFeatureTitleLine(trimmed)) {
      const title = trimmed
      index += 1
      while (index < lines.length && isBlankLine(lines[index] ?? '')) index += 1
      const dataLine = lines[index]?.trim() ?? ''
      if (!isTableRowLine(dataLine)) break

      const cells = dataLine.split('\t').map(normalizeRawTsvCell)
      const description = cells[0]?.trim() ?? ''
      const featureCell = description ? `**${title}**<br>${description}` : `**${title}**`
      bodyRows.push([featureCell, ...cells.slice(1)])
      index += 1
      continue
    }

    if (isTableRowLine(trimmed)) {
      bodyRows.push(['', ...normalizeRawTsvRow(trimmed).split('\t')])
      index += 1
      continue
    }

    break
  }

  return {
    rows: [headerRow, ...bodyRows],
    nextIndex: index,
  }
}

/** Converts Ultimate Weapon Plus scaling grids in raw Fandom text exports. */
export function convertFandomScalingAbilityMatrices(rawRegion: string): string {
  const lines = rawRegion.replace(/\r/g, '').split('\n')
  const output: string[] = []
  let index = 0
  let pendingMatrixRows: string[][] = []

  const flushPendingMatrix = () => {
    if (pendingMatrixRows.length === 0) return
    output.push(...renderFandomMarkdownTable(pendingMatrixRows))
    pendingMatrixRows = []
  }

  while (index < lines.length) {
    const segment = collectScalingMatrixSegment(lines, index)
    if (segment) {
      pendingMatrixRows.push(...segment.rows)
      index = segment.nextIndex
      continue
    }

    flushPendingMatrix()
    output.push(lines[index] ?? '')
    index += 1
  }

  flushPendingMatrix()
  return output.join('\n').trim()
}

export function preprocessFandomRawTableRegions(raw: string): string {
  return convertFandomScalingAbilityMatrices(raw)
}

export function looksLikeDotSeparatedTableFallback(text: string): boolean {
  return /(?:^|\n)[A-Za-z][^\n]{0,48} · (?:\d|[x\d.%])/m.test(text)
}

export function countMarkdownTableRows(text: string): number {
  return (text.match(/^\|[^\n]+\|$/gm) ?? []).length
}
